# Candidate (B5) for TASK-PAY-018 (webhook_signature_header)
def build_request(data):
    return {
        'path': '/v2/payment/webhook_signature_header/task-pay-018',
        'body': {
            'signed_webhook_event': {
                'amount_subunits': int(data['amount_cents']),
                'currency': data['currency'],
                'source_route': data['source'],
                'destination_route': data['destination'],
                'token_ref': data['extra_token']
            }
        },
        'headers': {
            'X-Nexus-Signature': data['idempotency_key']
        }
    }

def capture_intent(data):
    return build_request(data)

